SELECT
    /* overlap area in square kilometres */
    ST_Area(
        ST_Transform(intersection, 'EPSG:5070', 'EPSG:4326', always_xy := true)
    ) / 1e6 AS overlap_area_sqkm,
    /* overlap geometry as GeoJSON (in EPSG:4326) */
    ST_AsGeoJSON(
        ST_Transform(intersection, 'EPSG:5070', 'EPSG:4326', always_xy := true)
    ) AS overlap_geojson
FROM (
    SELECT
        ST_Intersection(hull_solar, hull_wind) AS intersection
    FROM (
        SELECT
            /* convex hull of all US Solar plants */
            (SELECT ST_ConvexHull(
                        ST_Collect(LIST(geometry))
                    )
             FROM power_plants
             WHERE primary_fuel = 'Solar' AND country = 'USA') AS hull_solar,
            /* convex hull of all US Wind plants */
            (SELECT ST_ConvexHull(
                        ST_Collect(LIST(geometry))
                    )
             FROM power_plants
             WHERE primary_fuel = 'Wind' AND country = 'USA') AS hull_wind
    ) AS hulls
) AS inter

SELECT
    ST_AsGeoJSON(
        ST_ConvexHull(
            ST_Collect(ARRAY_AGG(geometry))
        )
    ) AS convex_hull_geojson,
    ST_Area_Spheroid(
        ST_ConvexHull(
            ST_Collect(ARRAY_AGG(geometry))
        )
    ) / 1e6 AS area_sq_km
FROM eu_nuts_regions
WHERE cntr_code = 'DE' AND levl_code = 3
